public class Solution extends Reader4 {
  public int read(char[] buf, int n) {
    char[] buf4 = new char[4];
    int copied = 0;
    while (copied < n) {
      int got = read4(buf4);
      for (int i = 0; i < got && copied < n; i++) buf[copied++] = buf4[i];
      if (got < 4) break;
    }
    return copied;
  }
}
